import{_ as s,l,o as r,c as o,v as E,p as S,x as n,d as t,i as A,S as p,b as a}from"./chunks/framework.InCnrqk-.js";const c=JSON.parse('{"title":"保证金模型 SPAN 与 SIMM","description":"","frontmatter":{"title":"保证金模型 SPAN 与 SIMM","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/span-simm.md","filePath":"quant/span-simm.md","lastUpdated":1789023840000}'),M={name:"quant/span-simm.md"};function d(m,e,B,h,u,I){const i=l("Mermaid");return r(),o("div",null,[e[1]||(e[1]=E('<h1 id="保证金模型-span-与-simm" tabindex="-1">保证金模型 SPAN 与 SIMM <a class="header-anchor" href="#保证金模型-span-与-simm" aria-label="Permalink to &quot;保证金模型 SPAN 与 SIMM&quot;">​</a></h1><div class="epigraph"><p>保证金要在清算违约之前留住足够的可变现抵押，覆盖「一天或数天内、在规定情景网格上」的潜在损失；它不是经济资本，也不等于银行账簿的 VaR，但和 VaR 共用同一类损失映射。</p><footer>—— CME SPAN 公开方法论；ISDA SIMM 公开方法论（非清算衍生品初始保证金）</footer></div><p><a href="/quant/component-es">上一课</a>表明正齐次风险度量可按 Euler 公式切成成分之和，ES 的成分是尾巴情景里各腿的条件期望；VaR 的 Euler 切片噪声大且度量不连贯。缺口是保证金不是资本切开。交易所清算与非清算 OTC 要的是须缴纳的初始保证金：地平线是保证金期，模型是网格最大损失或行业标定的敏感性加总，不是你估的 \\(\\Sigma\\)。本课对照 SPAN 与 ISDA SIMM。不重写条件期望。后课缺口风险默认已经读完：网格外的跳两套标准模型都会漏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>VaR/ES 服务限额与监管资本，测度可以是日常或压力年，地平线 1 日或 10 日，置信 99% 或 97.5% ES。保证金服务中央对手方或双边抵押：地平线往往是保证金期（MPOR，如 1–2 个清算日或 10 日非清算），覆盖的是清算违约到平仓完成。SPAN 用网格最大损失，不是概率分位数；SIMM 用监管/行业标定的风险权重，不是你估的 \\(\\Sigma\\)。把保证金当「另一种 VaR」会在回测上找错对象：SPAN 不会有 Kupiec 违反率，它有的是情景是否覆盖了真实平仓路径。</p><p>清算会员还面对变动保证金、额外保证金、清算基金。本篇只写初始保证金的组合模型。融资与 haircut 见 <a href="/quant/leverage-liquidation">杠杆与强平</a>；市场冲击见 <a href="/quant/liquidity-adjusted-var">流动性调整</a>。</p><h3 id="span-扫描风险不是蒙特卡洛" tabindex="-1">SPAN：扫描风险不是蒙特卡洛 <a class="header-anchor" href="#span-扫描风险不是蒙特卡洛" aria-label="Permalink to &quot;SPAN：扫描风险不是蒙特卡洛&quot;">​</a></h3><p>CME 公开的 SPAN 结构大致是：对每个合约定义风险数组（risk array）——标的价格上下若干档、波动上下，再加上极端价格移动等固定情景（经典实现里常见十六个扫描点一类，具体档位以当时交易所文件为准）。每个情景下用定价模型重估期权与期货，得到损失。扫描风险取网格上的最大损失。同一商品内不同到期之间给价差抵扣（intra-commodity spread），不同商品之间若交易所承认对冲关系则给跨商品抵扣（inter-commodity spread）。空头期权另有最低保证金（short option minimum），防止网格在极低 Vega 时把保证金收到接近零。</p><p><span class="marginnote">SPAN 的「最大网格损失」对网格外的跳没有概率陈述。缺口若比最极端扫描档还大，保证金可以不够。这是网格模型的边界，要用附加保证金或缺口产品限额补，而不是加密扫描档位假装成连续分布。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>SPAN 实务要点。</strong> 输入是净持仓与合约的风险数组参数（由清算所按产品公布，不是会员自己估波动）。输出是初始保证金。会员可在组合层看到扫描风险、抵扣、SOM 的分解，便于解释「为什么加了一笔日历价差保证金反而下降」。对冲若未被列为合法价差（错误到期、错误比例），抵扣为零，保证金接近两腿之和。工程上应把交易所价差表当成数据依赖：表一更新，保证金跳跃与 P&amp;L 无关。</p><p><strong>ISDA SIMM。</strong> 公开方法论按产品收集风险因子敏感性：利率、信用（合格与非合格）、股票、商品、外汇等风险类别，每类内再分 delta、vega、曲率。每项敏感性乘风险权重，类别内用规定相关矩阵加总，类别之间再加总；集中度超过阈值则提高权重。曲率项处理非线性，避免纯 delta 在期权上不够。参数由 ISDA 定期校准并公布，用户不得用内部 \\(\\Sigma\\) 替换——这正是「标准」的含义：双边可复现、可对账。</p><p><strong>与 FRTB SA 的相似与不同。</strong> 二者都是敏感性 × 权重 × 相关。FRTB 目标是资本、含 DRC 与 RRAO、有流动性期限；SIMM 目标是 IM、覆盖保证金期、不含银行资本里那些附加模块的全部。不得把 FRTB 资本直接当 SIMM，也不得把 SIMM 当内部模型 ES。对照仍有用：同一套希腊字母应能同时喂 SIMM 与 SA，差异来自权重与相关，而不是来自漏掉的风险因子。</p><h3 id="保证金期、门槛与对账" tabindex="-1">保证金期、门槛与对账 <a class="header-anchor" href="#保证金期、门槛与对账" aria-label="Permalink to &quot;保证金期、门槛与对账&quot;">​</a></h3><p>非清算 IM 通常有门槛与最低转移金额，SIMM 给出的是门槛之上应有的总 IM。MPOR 越长，权重隐含的波动越大。清算 SPAN 的地平线嵌在风险数组的价格档里，不单独报一个 \\(\\alpha\\)。双边对账：双方用同一 SIMM 版本、同一敏感性定义（包括曲线分桶、vega 的波动定义），差异应在舍入与快照时间，而不是模型选择。敏感性若用内部模型与对手用供应商模型，对账失败会变成保证金争议，属于运营风险。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SPAN 的机制是最坏网格点：离散情景下的 \\(\\max g(\\Delta S,\\Delta\\sigma)\\)。抵扣的机制是监管承认的分散化，不是估计相关。因此 SPAN 对「网格内的非线性」敏感（期权重定价），对「网格外的跳」与「未被列表的对冲」不敏感。SIMM 的机制是线性（加曲率修正）的加权敏感性：快、可加总、可对账；深度虚值、障碍、复杂路径依赖若不能被 delta/vega/曲率抓住，会漏。这与 FRTB 用 RRAO 抓剩余风险是同一逻辑：标准敏感性法有覆盖缺口。</p><p>保证金与 VaR 的顺周期也不同。SPAN 数组由清算所更新，危机中档位与保证金乘数上调，是清算所的政策，不是你窗口里的 \\(\\sigma_t\\)。SIMM 权重定期校准，不随你昨日收益更新。内部条件 VaR 会在高 \\(\\sigma_t\\) 日自动升限额；保证金可能滞后或一步跳。交易台若用 VaR 管仓、用保证金管融资，两套数字的时间差本身是流动性风险。</p><p><span class="marginnote">组合在 SPAN 里因跨商品抵扣看起来便宜，在 SIMM 里可能很贵（OTC 对冲腿不在同一清算池）。清算与非清算的保证金不能净额时，对冲在保证金上可以是正的现金占用。经济对冲不等于保证金对冲。</span></p><h3 id="回测与覆盖" tabindex="-1">回测与覆盖 <a class="header-anchor" href="#回测与覆盖" aria-label="Permalink to &quot;回测与覆盖&quot;">​</a></h3><p>清算所会对 SPAN 做覆盖回测：实现损失超过初始保证金的频率是否符合设计。这与 Kupiec 类似，但损失定义是会员组合的清算路径，不是中间价。内部不得用「我们 SPAN 很少被突破」证明经济资本足够：突破少可能是保证金过保守，也可能是样本未含网格外缺口。SIMM 的回测由行业与监管在校准周期里做，单家机构应做的是敏感性完整性：漏一个十档利率点，IM 可以安静地偏少。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>SPAN 版本、数组、价差表以交易所当前公开文件为准，会随产品上市而变。SIMM 版本号必须与对手一致，升级是双边项目。两套模型都不含你自己的缺口产品在网格外的跳；结构化发行应另做 <a href="/quant/gap-risk">缺口风险</a> 限额。也不含 CCP 违约基金与评估权。把保证金最小化当成目标函数，会把仓位赶到抵扣表承认的格子里，形成拥挤；那是约束下的最优，不是风险最小。</p><p>不要用内部 MC VaR 去「验证」SIMM 高低：测度、地平线、置信都不同。可以验证的是：SIMM 输入的希腊字母是否与内部定价器一致。不要为降低 SPAN 而把期权改到扫描模型定价不准的微笑区域却不调风险数组——数组是清算所的，不是你的校准盘。</p><p><span class="marginnote">保证金是现金与合格抵押的占用，机会成本进入 <a href="/quant/net-edge">扣费后边缘</a>，不进入 VaR。策略评估若只报夏普不报 IM 占用，会高估需要双边保证金的 OTC 结构。</span></p>',25)),(r(),S(p,null,{default:n(()=>[A(i,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20Fut%5B%22%E6%9C%9F%E8%B4%A7%E6%9C%9F%E6%9D%83%E6%8C%81%E4%BB%93%22%5D%20--%3E%20SPAN%5B%22SPAN%3A%20%E7%BD%91%E6%A0%BC%E6%9C%80%E5%A4%A7%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20SPAN%20--%3E%20Spr%5B%22%E5%93%81%E7%A7%8D%E5%86%85%20%2F%20%E8%B7%A8%E5%93%81%E7%A7%8D%E6%8A%B5%E6%89%A3%22%5D%0A%20%20Spr%20--%3E%20SOM%5B%22%E7%A9%BA%E5%A4%B4%E6%9C%9F%E6%9D%83%E4%B8%8B%E9%99%90%22%5D%0A%20%20SOM%20--%3E%20IM1%5B%22%E6%B8%85%E7%AE%97%E5%88%9D%E5%A7%8B%E4%BF%9D%E8%AF%81%E9%87%91%22%5D%0A%20%20OTC%5B%22%E9%9D%9E%E6%B8%85%E7%AE%97%20OTC%20%E6%95%8F%E6%84%9F%E6%80%A7%22%5D%20--%3E%20SIMM%5B%22SIMM%3A%20%E6%9D%83%E9%87%8D%20%C3%97%20%E7%9B%B8%E5%85%B3%22%5D%0A%20%20SIMM%20--%3E%20Conc%5B%22%E9%9B%86%E4%B8%AD%E5%BA%A6%E4%B8%8A%E8%B0%83%22%5D%0A%20%20Conc%20--%3E%20IM2%5B%22%E5%8F%8C%E8%BE%B9%E5%88%9D%E5%A7%8B%E4%BF%9D%E8%AF%81%E9%87%91%22%5D%0A%20%20IM1%20--%3E%20Cash%5B%22%E6%8A%B5%E6%8A%BC%E5%8D%A0%E7%94%A8%22%5D%0A%20%20IM2%20--%3E%20Cash%0A%20%20VaR%5B%22%E5%86%85%E9%83%A8%20VaR%20%2F%20ES%22%5D%20--%3E%20Lim%5B%22%E9%99%90%E9%A2%9D%E4%B8%8E%E8%B5%84%E6%9C%AC%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[t("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"SPAN 用价格–波动网格的最大损失加官方价差抵扣，服务清算初始保证金，不是概率 VaR。"),a("li",null,"ISDA SIMM 用公开参数的敏感性加总，服务非清算 IM，可双边对账，精神近 FRTB SA 而非内部模型。"),a("li",null,"网格外缺口与无法被希腊字母抓住的奇异风险，两套标准模型都会漏，须另设限额。"),a("li",null,"经济对冲在不同清算池、不同模型里可以变成保证金增加。"),a("li",null,[t("出处：CME SPAN 公开方法论文件；ISDA "),a("em",null,"SIMM Methodology"),t(" 公开版本；非清算保证金规则见 BCBS–IOSCO 保证金框架；资本侧对照 BCBS FRTB 标准法。")])],-1))])}const D=s(M,[["render",d]]);export{c as __pageData,D as default};
